<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$s=$pdo->prepare('SELECT e.*,i.full_name instructor FROM evaluations e JOIN instructors i ON i.id=e.instructor_id WHERE e.evaluator_user_id=? ORDER BY e.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();page_header('My evaluations');show_flash();?><div class="page-intro"><div><div class="eyebrow">PERSONAL ACTIVITY</div><h1>My evaluations</h1><p>Track the evaluations submitted through your account.</p></div><a class="btn primary" href="<?=BASE_URL?>/evaluate.php">＋ New evaluation</a></div><section class="panel table-wrap"><table><thead><tr><th>ID</th><th>Instructor</th><th>Form</th><th>Academic year</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6">No evaluations submitted yet.</td></tr><?php endif;foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['instructor'])?></td><td><?=e(ucwords(str_replace('_',' ',$r['evaluator_type'])))?></td><td><?=e($r['academic_year'])?></td><td><span class="status"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></section><?php page_footer();?>